// Catalog Overhaul Pack: STORY_FAMILIES_1.md, SF1 "The Region in Crisis" (reports, strands, climaxes, rescues, the climax ally).
// Build: npm run co:build -- families-a-1. Flags follow the pack (crisis.blackout.on -> crisis-blackout-on).
// Severity is the region's crisis meter (core/story/crisis.ts): it rises one a stage; a strand node that "holds it" takes one back.
import { ch, fight, flag, flagAt, fr, front, heal, hurt, item, join, leave, lv, out, room, rp, wild, $, type Json } from '../dsl.ts';
import { aid, crisis, crisisAt, disaster, grunt, hasType, is, kind, knows, later, moment, not, region, safe, sub, temp, trust, trusts, v } from './_fa.ts';

export const CATEGORY = 'families-a';

const start = (s: string): Json[] => [flag(`crisis-${s}-on`), flag('crisis-strand-open'), flag('crisis-beat')];
const end = (s: string, first: string): Json[] => [flagAt(`crisis-${s}-first-${first}`), flag(`crisis-${s}-ended`), flag('crisis-strand-open', -9), flag('crisis-ally-asked', -9), flag('crisis-ally-split', -9), flag('crisis-ally-together', -9), flag('crisis-beat', -9), crisis(-5)];
const reportNeeds = (s: string): Json[] => [not('crisis-strand-open'), not(`crisis-${s}-on`)];
const holds = crisis(-1);

interface Site { label: string; key: string; text: string; together: string }
interface Climax {
  s: string; parent: string; id: string; name: string; intro: string; a: Site; b: Site;
  splitLabel?: string; split: { text: string; foe: string; sprite: string; types: string[]; waves?: number; won: string; lost: string; fx?: Json[] };
  both: string; ally: string;
  lost: { name: string; intro: string; label: string; text: string; fx: Json[]; unless?: Json[] };
  special?: Json; extraChoice?: Json;
}

/** A strand's climax ("two places need you at once") and its Severity 4 ending. */
function climax(c: Climax): Json[] {
  const done = (first: string, n = 2): Json[] => [...end(c.s, first), ...kind(n), aid(1)];
  const site = (x: Site): Json => ch(x.label, out(x.text, ...done(x.key)));
  const splitChoice = ch(c.splitLabel ?? 'Split my team.', fight(c.split.text, disaster(c.split.foe, c.split.sprite, c.split.types, {
    waves: c.split.waves ?? 2, lv: 1,
    win: [...done('split', 3), lv(1, 'party'), moment(c.split.won, 75), ...(c.split.fx ?? [])],
    lose: [...end(c.s, 'split-lost'), moment(c.split.lost, 70)],
  })));
  const together = (x: Site): Json => ch(x.label, fight(x.together, disaster(c.split.foe, c.split.sprite, c.split.types, { size: 4, format: 'doubles', win: [...done(x.key), lv(1, 'party')], lose: [...end(c.s, `${x.key}-lost`)] })));
  const bothSite = (x: Site): Json => ch(x.label, out(c.both, ...done(x.key, 3), flag('crisis-saved-both')));
  const remembers = [
    ...(c.special ? [c.special] : []),
    v('ally-split', [is('crisis-ally-split')], { notice: `${c.ally} You only have to choose where you stand; the other place has someone running for it already.`, hide: [0, 1, 2], add: [bothSite(c.a), bothSite(c.b)] }),
    v('ally-together', [is('crisis-ally-together')], { notice: 'The one who came for you falls into step at your shoulder. Wherever you go, you go as two.', hide: [0, 1], add: [together(c.a), together(c.b)] }),
  ].slice(0, 3);
  return [
    sub(c.parent, c.id, c.name, c.intro, [site(c.a), site(c.b), splitChoice, ...(c.extraChoice ? [c.extraChoice] : [])], {
      callback: true, rarity: 'rare', requires: [is(`crisis-${c.s}-on`), not(`crisis-${c.s}-ended`), later(`crisis-${c.s}-on`, { stages: 1 }), crisisAt(0, 3)], remembers,
    }),
    sub(c.parent, `crisis-${c.s}-lost`, c.lost.name, c.lost.intro, [ch(c.lost.label, out(c.lost.text, ...end(c.s, 'nobody'), ...c.lost.fx))], {
      callback: true, rarity: 'rare', requires: [is(`crisis-${c.s}-on`), not(`crisis-${c.s}-ended`), crisisAt(4), ...(c.lost.unless ?? [])],
    }),
  ];
}

// ---------- SF1.1 The Lights Went Out ----------
