((FACTORY[2]!.choices as Json[])[0]!.success as { effects: Json[] }).effects.push(region('Bottled water: prices are up by a tenth', { kind: 'priceMultiplier', group: 'all', value: 1.1 }));

// ---------- SF1.4 The Fever ----------
const cough = region('The cough: your Pokémon are a little slower', { kind: 'statMultiplier', stat: 'spe', value: 0.9 });
const FEVER: Json[] = [
  {
    id: 'crisis-report-outbreak', requires: reportNeeds('fever'),
    intro: 'A ranger station with its door propped open. Inside, a ranger is asleep face-down on her desk with a pen still in her hand. On blankets along the wall lie three sick Pokémon, breathing fast and shallow. One of them, a Skitty, lifts its head when you come in and cannot hold it up. The ranger jerks awake. Ines: "Sorry. Sorry. Haven\'t slept." She rubs her face with both hands. "Same fever everywhere. Wild and owned. Starts as a cough. Then they won\'t eat." She looks at the blankets. "I think it\'s in the water. Or a Pokémon carrying it. I can\'t tell which and I can\'t test both."',
    choices: [
      ch('Test the water.', out('Ines hands you three stoppered jars and a map with three streams circled. You fill one at each: the spring, the ford, the pond where everything drinks. Back at the station she holds each to the lamp and adds her drops, and waits, and all three stay clear. "Clean." She breathes out. "It isn\'t the water. That\'s half the question gone."', ...start('fever'), flag('crisis-fever-water'), room('crisis-report-outbreak'))),
      ch('Find the carrier.', out('You follow the cough. A sick Rattata here, a wheezing Pidgey a mile on, each a little fresher than the last, a trail of small miseries pointing north. It ends at a stand of bare trees white with Swablu, a whole migrating flock, hundreds, and every one of them coughing like a tiny door creaking. They carried it in on the wind. They did not know. They look as sorry as anything you have ever seen.', ...start('fever'), flag('crisis-fever-carrier'), room('crisis-report-outbreak'))),
      ch('Help with the sick ones.', out('You take the night shift so that Ines can sleep in a real bed. Cool cloths. Water from a spoon. The Skitty will not drink for her, but it drinks for you, a drop at a time, with one paw resting on your wrist as if to keep you there. By morning its breathing has slowed. It watches you pack with enormous eyes. It will know you again, anywhere.', ...start('fever'), holds, fr(10, 'party'), flag('crisis-fever-skitty'), { kind: 'rest' }, ...kind())),
    ],
    remembers: [
      v('both-tested', [is('crisis-fever-water'), is('crisis-fever-carrier')], { intro: 'Ines has the jars lined up clear on one side of her desk and your map of the flock on the other. She is wide awake now. Ines: "Not the water. The Swablu. You\'ve given me the whole answer." She is already pulling down books. "With both I can make the medicine properly. Give me until the roost is found again."', hide: [0, 1, 2], add: [ch('Leave her to her work.', out('She does not look up when you go. On the blankets, the Skitty watches you all the way to the door.', flag('crisis-beat')))] }),
      v('water-tested', [is('crisis-fever-water')], { intro: 'The station again. Three clear jars stand on the desk. Ines: "It isn\'t the water. So it\'s being carried. If someone could find what\'s carrying it..." She looks at the three on the blankets, and does not finish.', hide: [0] }),
      v('carrier-found', [is('crisis-fever-carrier')], { intro: 'The station again. Ines has your sketch of the Swablu roost pinned over her desk. Ines: "A whole flock. Poor things." She frowns. "But if it\'s in the streams as well, curing the birds won\'t end it. I\'d want the water ruled out."', hide: [1] }),
    ],
  },
  sub('crisis-report-outbreak', 'crisis-fever-cough', 'The Cough', 'One of your own team stops on the road and makes a small, dry, creaking sound. Then again. It looks up at you, embarrassed, as if it has done something wrong. It has not. It has only been walking beside you through a sick country.', [
    ch('Keep it warm.', out('You wrap it in your own jacket and slow your pace to match its pace. Ines told you the fever is never the end of anyone, only a long, tired week. It leans on your leg when you stop. It is slower. It is not leaving your side.', cough, fr(6, 'party'), flag('crisis-fever-coughing'))),
  ], { callback: true, requires: [is('crisis-fever-on'), not('crisis-fever-ended'), not('crisis-fever-coughing'), crisisAt(2)] }),
  ...climax({
    s: 'fever', parent: 'crisis-report-outbreak', id: 'crisis-fever-climax', name: 'Roost or Kennels',
    intro: 'Ines meets you on the station step with a single wooden case held against her chest like a child. Inside, in straw, are a dozen small brown bottles. Ines: "We\'ve got enough medicine for one place. The flock\'s roost, or the town kennels." She has clearly been asking herself the same question all night, and is ashamed of how glad she is to hand it to someone else.',
    a: { label: 'The roost.', key: 'roost', text: 'You carry the case to the bare trees and dose the Swablu one by one, hundreds of small beaks, until the bottles are empty and the creaking in the branches has gone quiet. The fever ends where it began. In town, the kennel Pokémon get better the slow way, on rest and broth, over weeks. Two of their owners find you in the street. One shouts. One just asks why the birds came first, and waits for an answer, holding a lead with nobody on the end of it.', together: 'You carry the case to the roost with your ally beside you.' },
    b: { label: 'The kennels.', key: 'kennels', text: 'You carry the case into town, and by evening every pet in the kennels has had its dose and is asleep with a full belly for the first time in days. A small boy sits with his Lillipup\'s head in his lap and will not be moved. Out at the bare trees, the flock lifts on the next north wind, still coughing. It will come down again a region further on. You will be there to hear it.', together: 'You carry the case to the kennels with your ally beside you.' },
    splitLabel: 'Split the dose.',
    split: { text: 'Ines counts the bottles into two rows with her lips moving. Half doses. Half for the birds, half for the pets. Getting it into a frightened flock and a frightened kennel on the same day takes every member of your team, and the sick do not always know that you are helping.', foe: 'The Fevered', sprite: 'swablu', types: ['flying', 'normal'], won: 'You split the medicine between the roost and the kennels. Both mended, slowly', lost: 'You split the medicine between the roost and the kennels, and could not get it all where it was needed', fx: [cough] },
    both: 'Two cases go out of the station door that morning in two directions. By nightfall the branches at the roost are quiet, and the kennels are full of sleeping animals, and Ines is asleep on her desk again with the pen in her hand. This time nobody wakes her.',
    ally: 'Your ally has taken the second strap of the case without being asked.',
    lost: { name: 'The Long Fever', intro: 'Another station, another ranger, the same cough behind the door. The fever outran everyone. This one tells you Ines is still working, three valleys back, on a medicine for a sickness that has already moved on.', label: 'Carry it with you.', text: 'For as long as you are in this region, something will always be coughing: in a hedge, in a kennel, at your own heel. It is never the end of anyone. It is only a whole country that is tired, and takes longer to mend than it should have.', fx: [cough, region('The long fever: healing items restore a quarter less', { kind: 'healingMultiplier', value: 0.75 }), moment('The fever was never stopped. It ran through the whole region', 70)] },
    special: v('second-batch', [is('crisis-fever-water'), is('crisis-fever-carrier')], {
      intro: 'Ines meets you on the station step with two wooden cases, one under each arm, grinning like someone who has not grinned in a month. Ines: "You ruled out the water and you found the flock. I knew exactly what I was making. So I made it twice." There is nothing to choose. There is only the carrying.',
      hide: [0, 1, 2],
      add: [ch('Take both cases.', out('The roost in the morning: hundreds of small beaks, and then quiet in the branches. The kennels by evening: a boy asleep on the floor with his Lillipup asleep on top of him. Two empty cases. Ines writes the recipe out three times and posts it to three other stations before she lets herself sit down.', ...end('fever', 'both'), ...kind(3), aid(1), flag('crisis-saved-both'), fr(8, 'party')))],
    }),
    extraChoice: ch('Split the dose. (Heal Bell)', out('Ines counts the bottles into two rows, half doses, not enough. Then your Pokémon lifts its head and rings. The sound goes through the station like clean water. On the blankets, three sick heads come up at once. "Do that at the roost," Ines whispers. "Do that at the kennels." A half dose and a Heal Bell, it turns out, is a whole cure. Nobody pays anything for it at all.', ...end('fever', 'split'), ...kind(3), aid(1), flag('crisis-saved-both')), { requires: [knows('heal-bell')] }),
  }),
  sub('crisis-report-outbreak', 'crisis-fever-next', 'The Flock Comes Down', 'A new region. A fence along the road with a line of small white shapes on the top rail, and before you are close enough to count them you hear it: a tiny, creaking, apologetic cough, a hundred times over. The Swablu know you. They shuffle along the rail to make room, as if you had come to sit with them.', [
    ch('Tell the nearest ranger.', out('The ranger here has never heard of Ines or her medicine. You draw the roost, and the bottles, and write down the station\'s name, and she pins it over her desk with a face that says she understands exactly what is about to begin. It begins a little sooner here because of a choice you made. It will end sooner too, because you said so.', crisis(1), flag('crisis-fever-warned'))),
  ], { callback: true, requires: [is('crisis-fever-first-kennels'), later('crisis-fever-first-kennels', { regions: 1 })] }),
];

// ---------- SF1.5 The fifth strand: Wildfire, Quake, Blizzard ----------
function quakeHazard(): Json[] {
  const slope = (type: string, label: string): Json => ch(label, out('Your Pokémon plants itself across the fall line and leans. The next shock comes, and the slope groans, and holds. The trail behind it stays open, for you and for everyone who will need to come down this hill in a hurry tonight.', fr(5, 'lead'), ...kind()), { requires: [hasType(type)] });
  return [
    ch('Go down the mine.', out('The hiker stares at you. Then he lets go of the tree and points. "Adit\'s behind that boulder. Twelve of them went down this morning." He swallows. "I\'ll hold the rope. I\'ll hold it as long as it takes."', room('crisis-quake-mine'))),
    slope('ground', 'Steady the slope.'), slope('rock', 'Steady the slope. (Rock-type)'),
  ];
}
